-- seed-state-legislators batch 03
-- States: MA, MI, MN, MS, MO, MT, NE, NV, NH, NJ
-- Paste into Supabase SQL Editor AFTER migration-selection-method-and-legislative.sql
-- Safe to re-run for these states.

delete from public.state_officials
where court_or_agency = 'Legislative Branch'
  and state_code in ('MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ');

insert into public.state_officials (
  full_name,
  title,
  court_or_agency,
  level,
  state_code,
  district_number,
  county_name,
  party,
  photo_url,
  selection_method,
  appointed_by
)
